<?php
require_once __DIR__.'/../includes/init.php';require_login();$page_title='Fee Appreciation';$students=$pdo->query("SELECT id,admission_no,full_name FROM students WHERE status='active' ORDER BY full_name")->fetchAll();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$q=$pdo->prepare('INSERT INTO fee_appreciation_records(student_id,appreciation_month,marks_awarded,eligibility_status,notes,created_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE marks_awarded=VALUES(marks_awarded),eligibility_status=VALUES(eligibility_status),notes=VALUES(notes)');$q->execute([(int)$_POST['student_id'],$_POST['month'].'-01',(float)$_POST['marks'],$_POST['status'],trim($_POST['notes']??''),$_SESSION['user_id']]);flash('Monthly appreciation record saved.');go('fees/appreciation.php');}catch(Throwable $e){$err='Record not saved. Check the selected values.';}}
$rows=$pdo->query('SELECT a.appreciation_month,a.marks_awarded,a.eligibility_status,s.full_name,s.admission_no FROM fee_appreciation_records a JOIN students s ON s.id=a.student_id ORDER BY a.appreciation_month DESC LIMIT 200')->fetchAll();require __DIR__.'/../includes/header.php';?><h1>Monthly Fee Appreciation</h1><div class="notice">Use only the eligibility rules and marks formally approved by PIPS administration. This screen records decisions; it does not decide eligibility automatically.</div><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif;?><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid"><div><label>Student</label><select name="student_id" required><option value="">Select</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=h($s['admission_no'].' - '.$s['full_name'])?></option><?php endforeach;?></select></div><div><label>Month</label><input type="month" name="month" required></div><div><label>Marks</label><input type="number" step="0.01" name="marks" min="0" required></div><div><label>Status</label><select name="status"><option value="pending">Pending</option><option value="eligible">Eligible</option><option value="not_eligible">Not eligible</option><option value="approved">Approved</option></select></div><div><label>Notes</label><input name="notes"></div></div><button>Save appreciation record</button></form></div><div class="panel"><h2>History</h2><table><tr><th>Month</th><th>Student</th><th>Admission</th><th>Marks</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['appreciation_month'])?></td><td><?=h($r['full_name'])?></td><td><?=h($r['admission_no'])?></td><td><?=h($r['marks_awarded'])?></td><td><?=h($r['eligibility_status'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php';?>